# Keeps every cache and temporary file of this portable interpreter inside the
# program folder, in the regenerable "cache" directory — never in data_user
# (user data) and never in system locations. Loaded automatically because
# python314._pth enables "import site". Must never break the interpreter.
try:
    import os
    from pathlib import Path

    _root = Path(__file__).resolve().parents[3]
    _cache = _root / "cache"
    _home = _cache / "home"
    _temp = _cache / "temp"
    for _d in (_cache / "pip", _cache / "uv", _cache / "huggingface", _home, _temp):
        _d.mkdir(parents=True, exist_ok=True)

    os.environ.update({
        "PIP_CACHE_DIR": str(_cache / "pip"),
        "PIP_DISABLE_PIP_VERSION_CHECK": "1",
        "UV_CACHE_DIR": str(_cache / "uv"),
        "HF_HOME": str(_cache / "huggingface"),
        "TEMP": str(_temp),
        "TMP": str(_temp),
        "TMPDIR": str(_temp),
        "USERPROFILE": str(_home),
        "HOME": str(_home),
        "XDG_CACHE_HOME": str(_cache),
        "XDG_CONFIG_HOME": str(_home),
        "XDG_DATA_HOME": str(_home),
    })
except Exception:
    pass
